class CreateProjectKeyRequest(BaseModel):
    name: str
    scopes: List[str]

@router.post("/api/v1/projects/{project_id}/api-keys")
def create_project_api_key(
    project_id: int,
    payload: CreateProjectKeyRequest,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    project = db.query(Project).filter(
        Project.id == project_id,
        Project.organization_id == current_user.organization_id
    ).first()
    if not project or not current_user.is_project_admin(project_id):
        raise HTTPException(status_code=403, detail="Forbidden: Cannot provision API key on this project")
    raw_token = secrets.token_hex(24)
    key = ProjectApiKey(
        project_id=project.id,
        name=payload.name,
        scopes=",".join(payload.scopes),
        key_hash=hashlib.sha256(raw_token.encode()).hexdigest()
    )
    db.add(key)
    db.commit()
    return {"key_id": key.id, "token": f"pk_{raw_token}"}
